#pragma once#include <assert.h>struct SHcdBase {  SHcdBase()    : bMappedToNames( FALSE )    , m_CurStep( 0 )  {    ZeroMemory( szDescription, sizeof(szDescription) );    ZeroMemory( szUnits, sizeof(szUnits) );  }  virtual void Fake(){}  int m_CurStep;  BOOL bMappedToNames;  char szDescription[64];  char szUnits[8];};struct SCommon_P{  int leftPinsC;  int upPinsC;  int rightPinsC;  int downPinsC;};//////////////////////////////////////////////////////////////////////////class anytype_W{public:  enum  {    eAnalog,    eDigital,  }Type;  union  {    int digital;    double analog;  }Value;public:  anytype_W &operator=( int other )  {    Value.digital = other ? 1 : 0;    Type = eDigital;    return *this;  }  anytype_W &operator=( double other )  {    Value.analog = other;    Type = eAnalog;    return *this;  }  operator int()  {    if( eDigital == Type)      return Value.digital;    return (int)Value.analog;  }  operator double()  {    if( eAnalog==Type )      return Value.analog;    return Value.digital;  }};//////////////////////////////////////////////////////////////////////////struct KAND_W {  int INL0;  int INL1;  int INL2;  int INL3;  int INL4;  int INL5;  int INL6;  int INL7;  int OUTR0;};struct KAND_P : public SCommon_P{  BOOL InvertInput0;  BOOL InvertInput1;  BOOL InvertInput2;  BOOL InvertInput3;  BOOL InvertInput4;  BOOL InvertInput5;  BOOL InvertInput6;  BOOL InvertInput7;};struct KAND : public SHcdBase, public KAND_W, public KAND_P{  enum{ TypeID = 3500};};//////////////////////////////////////////////////////////////////////////struct KOR_W {  int INL0;  int INL1;  int INL2;  int INL3;  int INL4;  int INL5;  int INL6;  int INL7;  int OUTR0;};struct KOR_P : public SCommon_P{  BOOL InvertInput0;  BOOL InvertInput1;  BOOL InvertInput2;  BOOL InvertInput3;  BOOL InvertInput4;  BOOL InvertInput5;  BOOL InvertInput6;  BOOL InvertInput7;};